    let router = emulator();
    let url = create_ok(&router, "batch-delete-clock", &json!({})).await;

    let bodies = ["m0", "m1", "m2"];
    for body in bodies {
        let _ = ok(
            &router,
            "SendMessage",
            json!({ "QueueUrl": url, "MessageBody": body }),
