                sqs::DELAY_SECONDS,
                sqs::QUEUE_TYPE_PARAMETER_REASON,
            )));
        }
        let delay = match input.delay_seconds {
            Some(requested) => i64::from(requested),
            None => queue.integer(sqs::DELAY_SECONDS),
        };
