    const NAME: &'static str = "ReceiveMessage";
    const INPUT_SCHEMA: &'static ::aws_smithy_schema::Schema = super::types::RECEIVE_MESSAGE_INPUT_SCHEMA;
    const OUTPUT_SCHEMA: &'static ::aws_smithy_schema::Schema = super::types::RECEIVE_MESSAGE_OUTPUT_SCHEMA;
    const SUCCESS_STATUS: u16 = 200u16;

    async fn handle(
