// SPDX-License-Identifier: CC0-1.0

//! The rules about a message's own members that `SendMessage` and every entry of
//! `SendMessageBatch` are judged by.
//!
//! They are written once here so the two operations cannot judge the same message
//! differently. Each rule answers a [`SendFault`], and the operation maps that onto the
//! error shape its own response has: a thrown error for a single send, a failed entry for
//! a batch.

use super::*;

/// Why a message was not accepted, before an operation words it in its own envelope.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SendFault {
    /// A parameter the message had to carry and did not.
    MissingParameter(&'static str),
    /// A parameter whose value the queue does not accept; the whole refusal sentence.
    InvalidParameterValue(String),
}

/// The members a FIFO queue orders and deduplicates a message by, as the send resolved them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FifoMembers {
    pub group_id: Option<String>,
    pub deduplication_id: Option<String>,
}

/// Resolve the `MessageGroupId` and the deduplication token a message is sent under.
///
/// "In FIFO queues, MessageGroupId organizes messages into distinct groups ... If you do
/// not provide a MessageGroupId when sending a message to a FIFO queue, the action
/// fails." A standard queue may carry one too ("In standard queues, using MessageGroupId
/// enables fair queues"), where it identifies a tenant and orders nothing.
///
/// The token is the one the request supplied or, on a FIFO queue, "if you aren't able to
/// provide a MessageDeduplicationId and you enable ContentBasedDeduplication for your
/// queue", a SHA-256 hash of `body`. "If you don't provide a MessageDeduplicationId and
/// the queue doesn't have ContentBasedDeduplication set, the action fails with an error."
/// A token on a standard queue is a parameter its type does not take.
///
/// The group is judged before the token, so a message with two faults is always refused
/// for the same one.
pub fn fifo_members(
    queue: &Queue,
    group_id: Option<&str>,
    deduplication_id: Option<&str>,
    body: &str,
) -> Result<FifoMembers, SendFault> {
    let fifo = queue.is_fifo();
    match group_id {
        Some(given) => {
            if let Some(reason) = message_token_refusal("MessageGroupId", given) {
                return Err(SendFault::InvalidParameterValue(reason));
            }
        }
        None if fifo => return Err(SendFault::MissingParameter("MessageGroupId")),
        None => {}
    }

    let deduplication_id = match deduplication_id {
        Some(given) => {
            if !fifo {
                return Err(SendFault::InvalidParameterValue(invalid_parameter_message(
                    given,
                    "MessageDeduplicationId",
                    QUEUE_TYPE_PARAMETER_REASON,
                )));
            }
            if let Some(reason) = message_token_refusal("MessageDeduplicationId", given) {
                return Err(SendFault::InvalidParameterValue(reason));
            }
            Some(given.to_string())
        }
        None if fifo && queue.content_based_deduplication() => {
            Some(content_deduplication_token(body))
        }
        None if fifo => {
            return Err(SendFault::InvalidParameterValue(NO_DEDUPLICATION_ID.to_string()));
        }
        None => None,
    };

    Ok(FifoMembers {
        group_id: group_id.map(str::to_string),
        deduplication_id,
    })
}

/// The delay, in seconds, a message is held back for: the one the request names, or the
/// queue's own `DelaySeconds` when it names none.
///
/// "When you set FifoQueue, you can't set DelaySeconds per message. You can set this
/// parameter only on a queue level." What a FIFO queue cannot honour is a message held
/// back from its group, so it is a POSITIVE per-message delay that is refused there; a
/// delay of zero asks for nothing the queue does not already do. Either way the value
/// must be inside the range the model documents for the attribute.
pub fn message_delay(queue: &Queue, requested: Option<i32>) -> Result<i64, SendFault> {
    if let Some(requested) = requested.filter(|delay| queue.is_fifo() && *delay > 0) {
        return Err(SendFault::InvalidParameterValue(invalid_parameter_message(
            &requested.to_string(),
            DELAY_SECONDS,
            QUEUE_TYPE_PARAMETER_REASON,
        )));
    }
    let delay = requested.map_or_else(|| queue.integer(DELAY_SECONDS), i64::from);
    match delay_seconds_refusal(delay) {
        Some(reason) => Err(SendFault::InvalidParameterValue(reason)),
        None => Ok(delay),
    }
}

